307    hb_blob_t *sanitize_blob (hb_blob_t *blob)
   308    {
   309      bool sane;
   310
   311      init (blob);
   312
   313    retry:
   314      DEBUG_MSG_FUNC (SANITIZE, start, "start");
   315
   316      start_processing ();
   317
   318      if (unlikely (!start))
   319      {
   320        end_processing ();
   321        return blob;
   322      }
   323
   324      Type *t = reinterpret_cast<Type *> (const_cast<char *> (start));
   325
   326      sane = t->sanitize (this);
   327      if (sane)
   328      {
   329        if (edit_count)
   330        {
   331          DEBUG_MSG_FUNC (SANITIZE, start, "passed first round with %d edits; going for second round", edit_count);
   332
   333          /* sanitize again to ensure no toe-stepping */
   334          edit_count = 0;
   335          sane = t->sanitize (this);
   336          if (edit_count) {
   337            DEBUG_MSG_FUNC (SANITIZE, start, "requested %d edits in second round; FAILLING", edit_count);
   338            sane = false;
   339          }
   340        }
   341      }
   342      else
   343      {
   344        if (edit_count && !writable) {
   345          start = hb_blob_get_data_writable (blob, nullptr);
   346          end = start + blob->length;
   347
   348          if (start)
   349          {
   350            writable = true;
   351            /* ok, we made it writable by relocating.  try again */
   352            DEBUG_MSG_FUNC (SANITIZE, start, "retry");
   353            goto retry;
   354          }
   355        }
   356      }
   357
   358      end_processing ();
   359
   360      DEBUG_MSG_FUNC (SANITIZE, start, sane ? "PASSED" : "FAILED");
   361      if (sane)
   362      {
   363        hb_blob_make_immutable (blob);
   364        return blob;
   365      }
   366      else
   367      {
   368        hb_blob_destroy (blob);
   369        return hb_blob_get_empty ();
   370      }
